async function handleListSessions(
  ws: WebSocket,
  userId: string | number,
  limit?: number,
  before?: SessionCursor,
  sessionStore?: SessionStore,
  options: MessageHandlerOptions = {}
): Promise<void> {
  if (!options.history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
    return;
  }

  const listFor = sessionStore?.listFor;
  if (!listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Session store does not support listing conversations');
    return;
  }

  try {
    const summaries = await listFor(userId, {limit, before});
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
        entryCount: s.entryCount,
      })),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list conversations', {userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

